  "generated_loss": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    weight = batch.get('weight', None)\n    delta = (lpw - lpl) * 0.5 + (advantage_w - advantage_l) * 0.5\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.0))\n    alpha = float(extra.get('hyperparams', {}).get('alpha', 1.0))\n    x = alpha * scale * delta\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n    if weight is not None:\n        loss = loss * weight\n    return loss.mean()"
