{
  "name": "pairwise_advantage_cost_gap_loss",
  "intuition": "This loss promotes preference for pairs with higher advantages and lower cost gaps, aligning with lower-is-better objective. It combines advantage signals and cost gap to guide the model toward more preferred options, utilizing logsigmoid to smoothly differentiate pairwise rankings.",
  "pseudocode": "loss = -mean(logsigmoid(advantage_w - advantage_l + alpha * (cost_gap)))",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "advantage_cost",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "pairwise",
    "other_hparams": "none"
  },
  "operators_used": ["logsigmoid", "mean", "add", "mul"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    alpha = float(extra.get('alpha', 1.0))\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    cost_gap = batch['cost_gap']\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    diff_adv = ops.sub(advantage_w, advantage_l)\n    diff_cost = ops.mul(alpha, cost_gap)\n    combined_signal = ops.add(diff_adv, diff_cost)\n    loss = ops.neg(ops.mean(ops.logsigmoid(combined_signal)))\n    return loss"
}
